import js from "@eslint/js"
import importPlugin from "eslint-plugin-import"
import unicorn from "eslint-plugin-unicorn"
import tseslint from "typescript-eslint"
import { ambientAuthority, invariants, swallowedCause, uninstalledSafety } from "../../../eslint.invariants.js"
import { jsdocConvention } from "../../../eslint.jsdoc.js"

export default tseslint.config(
  {
    ignores: ["**/dist", "**/build", "**/coverage"]
  },
  js.configs.recommended,
  importPlugin.flatConfigs.recommended,
  importPlugin.flatConfigs.typescript,
  {
    files: ["src/**/*.ts"],
    extends: [tseslint.configs.recommended],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname
      }
    },
    settings: {
      "import/resolver": {
        typescript: {
          project: ["./tsconfig.json"]
        }
      }
    },
    plugins: {
      unicorn
    },
    rules: {
      "@typescript-eslint/array-type": ["error", { default: "generic", readonly: "generic" }],
      "@typescript-eslint/consistent-type-imports": ["error", { fixStyle: "inline-type-imports" }],
      "@typescript-eslint/no-explicit-any": "off",
      "@typescript-eslint/no-import-type-side-effects": "error",
      "@typescript-eslint/no-unnecessary-type-assertion": "error",
      "@typescript-eslint/no-unnecessary-type-constraint": "error",
      "@typescript-eslint/no-unused-vars": ["error", { argsIgnorePattern: "^_", varsIgnorePattern: "^_" }],
      "@typescript-eslint/no-useless-empty-export": "error",
      "import/no-duplicates": "error",
      "import/no-empty-named-blocks": "error",
      "import/no-self-import": "error",
      "no-await-in-loop": "off",
      "no-console": "error",
      "no-fallthrough": "off",
      "no-shadow": "off",
      "no-unneeded-ternary": "error",
      "no-unused-vars": "off",
      "no-useless-concat": "error",
      "no-useless-constructor": "error",
      "no-var": "error",
      "object-shorthand": "off",
      "require-yield": "off",
      "unicorn/no-abusive-eslint-disable": "error",
      "unicorn/no-accessor-recursion": "error",
      "unicorn/prefer-array-flat-map": "error"
    }
  },
  ...jsdocConvention,
  ...invariants(uninstalledSafety, swallowedCause, ambientAuthority)
)

{
  "name": "@smthrs/notifications",
  "type": "module",
  "version": "1.0.0-rc.16",
  "license": "MIT",
  "smthrs": {
    "group": "agent"
  },
  "description": "Durable notification queue, admission policy, and journal projection for flows",
  "homepage": "https://github.com/smithersai/smithers",
  "repository": {
    "type": "git",
    "url": "https://github.com/smithersai/smithers.git",
    "directory": "packages/smithers/notifications"
  },
  "bugs": {
    "url": "https://github.com/smithersai/smithers/issues"
  },
  "tags": [
    "typescript",
    "effect",
    "journal",
    "durability"
  ],
  "keywords": [
    "typescript",
    "effect",
    "journal",
    "durability"
  ],
  "engines": {
    "node": ">=22.19.0"
  },
  "sideEffects": [],
  "exports": {
    "./package.json": "./package.json",
    ".": "./src/index.ts",
    "./internal/*": null,
    "./*/index": null,
    "./Alerts": "./src/Alerts.ts",
    "./Channels": "./src/Channels.ts",
    "./Inbox": "./src/Inbox.ts",
    "./Notification": "./src/Notification.ts",
    "./NotificationEvent": "./src/NotificationEvent.ts",
    "./NotificationQueue": "./src/NotificationQueue.ts",
    "./NotificationState": "./src/NotificationState.ts",
    "./Projection": "./src/Projection.ts",
    "./SteerPayload": "./src/SteerPayload.ts",
    "./index": "./src/index.ts"
  },
  "files": [
    "src/**/*.ts",
    "dist/**/*.js",
    "dist/**/*.js.map",
    "dist/**/*.d.ts",
    "dist/**/*.d.ts.map",
    "dist/**/package.json",
    "LICENSE",
    "README.md",
    "CHANGELOG.md",
    "docs/"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true,
    "tag": "next",
    "exports": {
      "./package.json": "./package.json",
      ".": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      },
      "./internal/*": null,
      "./*/index": null,
      "./Alerts": {
        "import": {
          "types": "./dist/esm/Alerts.d.ts",
          "default": "./dist/esm/Alerts.js"
        },
        "require": {
          "types": "./dist/cjs/Alerts.d.ts",
          "default": "./dist/cjs/Alerts.js"
        }
      },
      "./Channels": {
        "import": {
          "types": "./dist/esm/Channels.d.ts",
          "default": "./dist/esm/Channels.js"
        },
        "require": {
          "types": "./dist/cjs/Channels.d.ts",
          "default": "./dist/cjs/Channels.js"
        }
      },
      "./Inbox": {
        "import": {
          "types": "./dist/esm/Inbox.d.ts",
          "default": "./dist/esm/Inbox.js"
        },
        "require": {
          "types": "./dist/cjs/Inbox.d.ts",
          "default": "./dist/cjs/Inbox.js"
        }
      },
      "./Notification": {
        "import": {
          "types": "./dist/esm/Notification.d.ts",
          "default": "./dist/esm/Notification.js"
        },
        "require": {
          "types": "./dist/cjs/Notification.d.ts",
          "default": "./dist/cjs/Notification.js"
        }
      },
      "./NotificationEvent": {
        "import": {
          "types": "./dist/esm/NotificationEvent.d.ts",
          "default": "./dist/esm/NotificationEvent.js"
        },
        "require": {
          "types": "./dist/cjs/NotificationEvent.d.ts",
          "default": "./dist/cjs/NotificationEvent.js"
        }
      },
      "./NotificationQueue": {
        "import": {
          "types": "./dist/esm/NotificationQueue.d.ts",
          "default": "./dist/esm/NotificationQueue.js"
        },
        "require": {
          "types": "./dist/cjs/NotificationQueue.d.ts",
          "default": "./dist/cjs/NotificationQueue.js"
        }
      },
      "./NotificationState": {
        "import": {
          "types": "./dist/esm/NotificationState.d.ts",
          "default": "./dist/esm/NotificationState.js"
        },
        "require": {
          "types": "./dist/cjs/NotificationState.d.ts",
          "default": "./dist/cjs/NotificationState.js"
        }
      },
      "./Projection": {
        "import": {
          "types": "./dist/esm/Projection.d.ts",
          "default": "./dist/esm/Projection.js"
        },
        "require": {
          "types": "./dist/cjs/Projection.d.ts",
          "default": "./dist/cjs/Projection.js"
        }
      },
      "./SteerPayload": {
        "import": {
          "types": "./dist/esm/SteerPayload.d.ts",
          "default": "./dist/esm/SteerPayload.js"
        },
        "require": {
          "types": "./dist/cjs/SteerPayload.d.ts",
          "default": "./dist/cjs/SteerPayload.js"
        }
      },
      "./index": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      }
    }
  },
  "scripts": {
    "lint": "eslint src --max-warnings=0 && dprint check",
    "format": "dprint fmt",
    "build": "node scripts/build.mjs",
    "check": "vibelang -b tsconfig.json && vibelang -p tsconfig.test.json --noEmit",
    "circular": "node ../../repo-targets/scripts/circular.mjs",
    "test": "vitest",
    "coverage": "vitest --coverage"
  },
  "dependencies": {
    "@smthrs/canonical": "1.0.0-rc.16",
    "@smthrs/crypto": "1.0.0-rc.16",
    "@smthrs/journal": "1.0.0-rc.16"
  },
  "devDependencies": {
    "@effect/language-service": "0.87.2",
    "@effect/vitest": "4.0.5",
    "@eslint/js": "9.39.5",
    "@smthrs/database": "1.0.0-rc.16",
    "@types/node": "26.4.1",
    "@vitest/coverage-v8": "5.0.0",
    "dprint": "0.57.1",
    "effect": "4.0.5",
    "esbuild": "0.28.2",
    "eslint": "9.39.5",
    "eslint-import-resolver-typescript": "4.4.5",
    "eslint-plugin-import": "2.32.0",
    "eslint-plugin-jsdoc": "64.3.4",
    "eslint-plugin-unicorn": "65.0.0",
    "madge": "8.0.0",
    "typescript": "5.9.3",
    "typescript-eslint": "8.69.0",
    "vibelang": "0.0.8",
    "vibelang-vite": "0.0.8",
    "vitest": "5.0.0",
    "fast-check": "4.9.0"
  },
  "peerDependencies": {
    "effect": "4.0.5"
  }
}

import { tmpdir } from "node:os"
import { join } from "node:path"
import { fileURLToPath } from "node:url"
import vibelang from "vibelang-vite"
import { configDefaults, defineConfig } from "vitest/config"

export default defineConfig({
  plugins: [vibelang({ project: "tsconfig.test.json" })],
  test: {
    globalSetup: [
      fileURLToPath(new URL("../../repo-targets/test-utils/coverage-teardown.mjs", import.meta.url)),
      fileURLToPath(new URL("../../repo-targets/test-utils/test-process-environment.mjs", import.meta.url))
    ],
    include: [...configDefaults.include, "**/*.{test,spec}.vibe"],
    environment: "node",
    // House convention (see packages/smithers/flows/journal/vitest.config.ts): a finite 30 s
    // wall-clock budget so correct suites survive coverage-instrumented load
    // while a genuine hang still fails the run.
    testTimeout: 30_000,
    hookTimeout: 30_000,
    coverage: {
      enabled: true,
      provider: "v8",
      // Per-process report directory so concurrent vitest runs do not destroy
      // each other's coverage scratch state (issues #115/#121).
      reportsDirectory: join(tmpdir(), `flows-notifications-coverage-${process.pid}`),
      include: ["src/**"],
      thresholds: {
        branches: 100,
        functions: 100,
        lines: 100,
        statements: 100
      }
    }
  }
})
